46	 */
47	export interface ReadFileToolParams {
48	  /**
49	   * The path to the file to read
50	   */
51	  file_path: string;
52	
53	  /**
54	   * The line number to start reading from (optional, 1-based)
55	   */
56	  start_line?: number;
