77	/**
78	 * Validates a plan file path for safety (traversal) and existence.
79	 * @param planPath The untrusted path to the plan file.
80	 * @param plansDir The authorized project plans directory.
81	 * @param projectRoot The root directory of the project.
82	 * @returns An error message if validation fails, or null if successful.
83	 */
84	export async function validatePlanPath(
85	  planPath: string,
86	  plansDir: string,
87	  projectRoot: string,
88	): Promise<string | null> {
89	  try {
90	    const resolvedPath = resolveAndValidatePlanPath(
91	      planPath,
92	      plansDir,
93	      projectRoot,
94	    );
95	    if (!(await fileExists(resolvedPath))) {
96	      return PlanErrorMessages.FILE_NOT_FOUND(planPath);
97	    }
98	    return null;
99	  } catch {
100	    return PlanErrorMessages.PATH_ACCESS_DENIED(
101	      planPath,
102	      resolveToRealPath(plansDir),
103	    );
104	  }
105	}
