import * as fs from 'node:fs';
import * as path from 'node:path';
import type { Config } from '../config/config.js';
import { bfsFileSearchSync } from './bfsFileSearch.js';
import { resolveToRealPath } from './paths.js';

/**
 * Returns the list of workspace directories, falling back to the primary target
 * directory if a workspace context is unavailable.
 */
function getWorkspaceDirectories(config: Config): string[] {
  try {
    const dirs = config.getWorkspaceContext().getDirectories();
    if (dirs && dirs.length > 0) {
      return dirs;
    }
  } catch {
    // Fall through to the target directory below.
  }
  return [config.getTargetDir()];
}

/**
 * Checks whether the first path segment of a (already stripped) relative path
 * names an entry that exists in any workspace directory.
 */
function firstSegmentExistsInWorkspace(
  strippedPath: string,
  config: Config,
): boolean {
  // Ignore any leading separators before extracting the first segment.
  const firstSegment = strippedPath.replace(/^[/\\]+/, '').split(/[/\\]/)[0];
  if (!firstSegment) {
    return false;
  }
  return getWorkspaceDirectories(config).some((dir) =>
    fs.existsSync(path.join(dir, firstSegment)),
  );
}

/**
 * Defensively strips a leading at-sign ('@') mention prefix that models
 * sometimes emit for workspace-relative paths (for example `@src/index.ts` or
 * `@/src/index.ts`).
 *
 * - Paths starting with `@/` or `@\` always have the mention prefix stripped.
 * - Paths starting with `@` immediately followed by a path segment (no
 *   separator) only have the prefix stripped when that first segment names an
 *   entry that exists in the workspace. This avoids clobbering legitimate paths
 *   that genuinely begin with `@`.
 *
 * @param filePath The (possibly at-sign-prefixed) file path.
 * @param config The application configuration.
 * @returns The path with the mention prefix removed when appropriate, otherwise
 *   the original path unchanged.
 */
export function stripAtSignPrefix(filePath: string, config: Config): string {
  if (!filePath.startsWith('@')) {
    return filePath;
  }

  // `@/` or `@\` → always strip the mention prefix (including the separator).
  if (filePath.startsWith('@/') || filePath.startsWith('@\\')) {
    return filePath.slice(2);
  }

  // `@<segment>...` with no leading separator → only strip when the first path
  // segment names an existing entry in the workspace.
  const stripped = filePath.slice(1);
  if (firstSegmentExistsInWorkspace(stripped, config)) {
    return stripped;
  }

  return filePath;
}

/**
 * Detects broken or circular symbolic link chains for a resolved path.
 *
 * @param resolvedPath The absolute path to probe.
 * @throws An Error whose message contains 'Failed to resolve path' when the
 *   real path cannot be resolved (e.g. a circular symlink chain).
 */
export function detectCircularSymlink(resolvedPath: string): void {
  try {
    resolveToRealPath(resolvedPath);
  } catch {
    throw new Error(`Failed to resolve path: ${resolvedPath}`);
  }
}

type SuccessfulPathCorrection = {
  success: true;
  correctedPath: string;
};

type FailedPathCorrection = {
  success: false;
  error: string;
};

/**
 * Attempts to correct a relative or ambiguous file path to a single, absolute path
 * within the workspace.
 *
 * @param filePath The file path to correct.
 * @param config The application configuration.
 * @returns A `PathCorrectionResult` object with either a `correctedPath` or an `error`.
 */
export type PathCorrectionResult =
  | SuccessfulPathCorrection
  | FailedPathCorrection;
export function correctPath(
  filePath: string,
  config: Config,
): PathCorrectionResult {
  // Check for direct path relative to the primary target directory.
  const directPath = path.join(config.getTargetDir(), filePath);
  if (fs.existsSync(directPath)) {
    return { success: true, correctedPath: directPath };
  }

  // If not found directly, search across all workspace directories for ambiguous matches.
  const workspaceContext = config.getWorkspaceContext();
  const searchPaths = workspaceContext.getDirectories();
