import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';
import type { Config } from '../config/config.js';
import { createMockWorkspaceContext } from '../test-utils/mockWorkspaceContext.js';
import { FileDiscoveryService } from '../services/fileDiscoveryService.js';
import {
  correctPath,
  stripAtSignPrefix,
  detectCircularSymlink,
} from './pathCorrector.js';

describe('scratch at-sign', () => {
  let tempDir: string;
  let rootDir: string;
  let mockConfig: Config;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'scratch-'));
    rootDir = path.join(tempDir, 'root');
    fs.mkdirSync(path.join(rootDir, 'src'), { recursive: true });
    fs.writeFileSync(path.join(rootDir, 'src', 'foo.ts'), 'x');
    mockConfig = {
      getTargetDir: () => rootDir,
      getWorkspaceContext: () => createMockWorkspaceContext(rootDir),
      getFileService: () => new FileDiscoveryService(rootDir),
      getFileFilteringOptions: () => ({
        respectGitIgnore: true,
        respectGeminiIgnore: true,
      }),
    } as unknown as Config;
  });
  afterEach(() => fs.rmSync(tempDir, { recursive: true, force: true }));

  it('strips @/ always', () => {
    expect(stripAtSignPrefix('@/src/foo.ts', mockConfig)).toBe('src/foo.ts');
    expect(stripAtSignPrefix('@/nope/bar.ts', mockConfig)).toBe('nope/bar.ts');
  });

  it('strips @seg only when first seg exists', () => {
    expect(stripAtSignPrefix('@src/foo.ts', mockConfig)).toBe('src/foo.ts');
    expect(stripAtSignPrefix('@nope/bar.ts', mockConfig)).toBe('@nope/bar.ts');
  });

  it('correctPath returns absolute for @src new file', () => {
    const r = correctPath('@src/new.ts', mockConfig);
    expect(r.success).toBe(true);
    if (r.success)
      expect(r.correctedPath).toBe(path.join(rootDir, 'src', 'new.ts'));
  });

  it('detectCircularSymlink throws Failed to resolve path', () => {
    const a = path.join(rootDir, 'a');
    const b = path.join(rootDir, 'b');
    fs.symlinkSync(b, a);
    fs.symlinkSync(a, b);
    expect(() => detectCircularSymlink(a)).toThrow(/Failed to resolve path/);
